namespace Dataphyre\Panel;

/** Truthful runtime capability inventory for the cohesive Panel platform. */
final class PanelPlatformManifest implements \JsonSerializable {
	/** @param array<string,mixed> $payload */
	private function __construct(private readonly array $payload){}

	public static function inspect(?PanelPlatform $platform=null):self{
		$services=$platform?->serviceDescriptors()??[];$names=array_keys($services);$domains=[];
		foreach(self::catalogue()as$name=>$definition){
			$features=[];$implementations=[];$requiredAvailable=true;
			foreach($definition['features']as$feature=>$class){$exists=self::exists($class);$features[$feature]=$exists;$implementations[$feature]=$class;if(in_array($feature,$definition['required'],true)&&!$exists){$requiredAvailable=false;}}
			$domainServices=array_values(array_filter($names,static fn(string $service):bool=>str_starts_with($service,$definition['prefix'].'.')||$service===$definition['prefix']));sort($domainServices,SORT_STRING);
			$health=[];$missing=[];$invalid=[];$pending=[];
			foreach($definition['services']as$service=>$expected){
				$status=$platform?->serviceStatus($service,$expected)??['service'=>$service,'expected'=>$expected,'present'=>false,'valid'=>false,'state'=>'missing','actual'=>null];
				$health[$service]=$status;
				if(!$status['present']){$missing[]=$service;continue;}
				if(!$status['valid']){$invalid[]=$service;if($status['state']==='unresolved_factory'){$pending[]=$service;}}
			}
			$configured=$domainServices!==[];$baseReady=$requiredAvailable&&$configured&&$missing===[]&&$invalid===[];$cohesion=self::cohesion($name,$platform,$baseReady);
			$domains[$name]=['available'=>$requiredAvailable,'configured'=>$configured,'ready'=>$baseReady&&($cohesion['valid']??true),'features'=>$features,'implementations'=>$implementations,'services'=>$domainServices,'required_services'=>array_keys($definition['services']),'service_health'=>$health,'missing_services'=>$missing,'invalid_services'=>$invalid,'pending_services'=>$pending];
			if($cohesion!==null){$domains[$name]['cohesion']=$cohesion;}
		}
		$available=count(array_filter($domains,static fn(array $domain):bool=>$domain['available']));$configured=count(array_filter($domains,static fn(array $domain):bool=>$domain['configured']));$ready=count(array_filter($domains,static fn(array $domain):bool=>$domain['ready']));
		return new self(['type'=>'panel_platform_manifest','version'=>1,'domains'=>$domains,'services'=>$services,'counts'=>['domains'=>count($domains),'available'=>$available,'configured'=>$configured,'ready'=>$ready,'services'=>count($services)],'security'=>['raw_configuration_serialized'=>false,'secret_values_serialized'=>false,'global_mutable_state'=>false,'readiness_requires_typed_services'=>true,'readiness_requires_cohesive_graphs'=>true,'unresolved_factories_ready'=>false]]);
	}

	/** @return array<string,mixed>|null */ public function domain(string $name):?array{return $this->payload['domains'][self::name($name)]??null;}
	public function available(string $name):bool{return ($this->domain($name)['available']??false)===true;}
	public function configured(string $name):bool{return ($this->domain($name)['configured']??false)===true;}
	public function ready(string $name):bool{return ($this->domain($name)['ready']??false)===true;}
	/** @return array<string,mixed> */ public function jsonSerialize():array{return PanelManifestContract::stamp($this->payload);}

