	private static function name(string $name):string{$name=strtolower(trim($name));return trim(preg_replace('/[^a-z0-9]+/','_',$name)??'','_');}
	/** @return array{evaluated:bool,valid:bool,mismatches:list<string>}|null */
	private static function cohesion(string $domain,?PanelPlatform $platform,bool $eligible):?array{
		if(!in_array($domain,['operations_os','operations','distributed_operations','migrations','observability','workflows','automation','realtime','agent_workflows','authentication','iam','studio','localization','preferences','collaboration','packages','platform'],true)){return null;}
		if(!$platform instanceof PanelPlatform||!$eligible){return['evaluated'=>false,'valid'=>false,'mismatches'=>[]];}
		try{
			$mismatches=[];
			if($domain==='operations_os'){
